pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockConfig cfg;

    function setUp() public {
        cfg = new MockConfig();
        c = new C();
        c.initialize(address(cfg));
    }

    function testFuzz_property(address newCfgAddr, address actor) public {
        vm.assume(actor != address(0));
        // admissible domain: any address may be proposed, including address(0)
        vm.prank(actor);
