pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockConfig cfg;

    function setUp() public {
        c = new C();
        cfg = new MockConfig();
        c.initialize(address(cfg));
    }

    function testFuzz_property(address newCfgAddr) public {
        // 1. domain kept wide: any address, including address(0), is admissible
        // 2. drive c through updateLRTConfig as the admin (hasRole returns true for anyone)
        bool ok;
        try c.updateLRTConfig(newCfgAddr) {
            ok = true;
        } catch {
            ok = false;
        }
        // 3. GENERAL RULE: whenever updateLRTConfig succeeds, the proposed address was a
        //    valid nonzero address AND the stored config is exactly that address.
        //    The mutant succeeds on address(0) and stores it, breaking the rule.
        assertTrue(!(ok && (newCfgAddr == address(0) || c.lrtConfig() != newCfgAddr)));
    }
}

