        cfg = new FakeConfig();
        c.initialize(address(cfg));
    }

    function testFuzz_property(address newCfg) public {
        vm.assume(newCfg != address(0) && newCfg != address(cfg));
        vm.prank(address(0xA11CE));
        try c.updateLRTConfig(newCfg) {
