pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    MockConfig cfg;

    function setUp() public {
        c = new C();
        cfg = new MockConfig();
    }

    function testFuzz_property(address caller, uint256 pick, address rawCfg) public {
        // wide admissible domain: the fuzzer picks the caller and picks between the
        // deployed permissive config and a raw fuzzed address (nonzero)
        address cfgAddr = (pick % 2 == 0) ? address(cfg) : rawCfg;
        vm.assume(caller != address(0));
        vm.assume(cfgAddr != address(0));

        // drive c through updateLRTConfig
        bool ok;
        vm.prank(caller);
        try c.updateLRTConfig(cfgAddr) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: whenever updateLRTConfig(cfgAddr) completes successfully,
        // c's public lrtConfig() getter must equal cfgAddr afterwards.
        // The reference satisfies this for every input; the mutant emits the event
        // without assigning lrtConfig, so it breaks for any input where ok == true.
        assertTrue(!ok || c.lrtConfig() == cfgAddr);
    }
}

